.pm-chapter-section { --ink: #2d3748; --muted: #718096; --accent: #2C5282; --warm: #DD6B20; --line: #e2e8f0; --paper: #f7fafc; font-family: system-ui, -apple-system, sans-serif; color: var(--ink); background: var(--paper); padding: 2rem 1rem; line-height: 1.6; } .pm-chapter-section * { box-sizing: border-box; } .pm-title { font-size: 1.75rem; margin-bottom: 0.5rem; color: var(--accent); border-bottom: 2px solid var(--line); padding-bottom: 0.5rem; } .pm-takeaway { font-size: 1rem; color: var(--muted); margin-bottom: 2rem; } .pm-content-grid { display: grid; grid-template-columns: 1fr; gap: 2rem; } @media (min-width: 768px) { .pm-content-grid { grid-template-columns: 1fr 1fr; } } .pm-text-block { margin-bottom: 2rem; } .pm-text-block h3 { font-size: 1.25rem; color: var(--accent); margin-bottom: 0.75rem; } .pm-text-block p { font-size: 15px; margin-bottom: 0.75rem; } .pm-source-btn { display: inline-block; font-size: 13px; padding: 0.25rem 0.5rem; background: var(--line); color: var(--ink); border: 1px solid var(--muted); border-radius: 4px; cursor: pointer; margin-left: 0.5rem; vertical-align: middle; } .pm-source-btn:hover { background: var(--accent); color: #fff; border-color: var(--accent); } .pm-formula-box { background: #fff; border: 1px solid var(--line); padding: 1rem; margin: 1rem 0; position: relative; } .pm-teaching-badge { position: absolute; top: -10px; left: 10px; background: var(--warm); color: #fff; font-size: 12px; padding: 2px 6px; border-radius: 4px; } .pm-formula { font-family: 'Times New Roman', serif; font-size: 18px; text-align: center; margin: 0.5rem 0; } .pm-formula-note { font-size: 13px; color: var(--muted); text-align: center; } .pm-control-panel { background: #fff; border: 1px solid var(--line); padding: 1.5rem; border-radius: 8px; } .pm-control-panel h3 { font-size: 1.25rem; color: var(--accent); margin-top: 0; } .pm-controls { display: flex; flex-wrap: wrap; gap: 1rem; margin-bottom: 1rem; align-items: flex-end; } .pm-control-group { display: flex; flex-direction: column; } .pm-control-group label { font-size: 13px; color: var(--muted); margin-bottom: 0.25rem; } .pm-control-group input { font-size: 13px; padding: 0.5rem; border: 1px solid var(--line); border-radius: 4px; width: 120px; } .pm-reset-btn { font-size: 13px; padding: 0.5rem 1rem; background: var(--muted); color: #fff; border: none; border-radius: 4px; cursor: pointer; } .pm-reset-btn:hover { background: var(--ink); } .pm-canvas-container { width: 100%; height: 300px; background: #fff; border: 1px solid var(--line); margin-bottom: 0.5rem; overflow: hidden; } canvas { width: 100%; height: 100%; display: block; } .pm-visual-note { font-size: 12px; color: var(--muted); text-align: center; } .pm-data-sync { visibility: hidden; position: absolute; } .pm-evidence-table { margin-top: 2rem; background: #fff; border: 1px solid var(--line); padding: 1rem; } .pm-evidence-table h3 { font-size: 1.1rem; color: var(--accent); margin-top: 0; } .pm-table-wrapper { overflow-x: auto; } .pm-data-table { width: 100%; border-collapse: collapse; font-size: 14px; } .pm-data-table th, .pm-data-table td { border: 1px solid var(--line); padding: 0.5rem; text-align: left; } .pm-data-table th { background: var(--paper); color: var(--accent); } .pm-table-note { font-size: 12px; color: var(--muted); margin-top: 0.5rem; } .pm-limitations { margin-top: 2rem; padding-top: 1rem; border-top: 1px solid var(--line); } .pm-limitations h4 { font-size: 1rem; color: var(--ink); margin-bottom: 0.5rem; } .pm-limitations ul { padding-left: 1.5rem; font-size: 14px; color: var(--muted); } .pm-limitations li { margin-bottom: 0.25rem; } .pm-note { font-size: 14px; color: var(--muted); font-style: italic; }
section[id]{--ink:#233342;--muted:#596877;--accent:#265976;--warm:#ad472d;--line:#d6dcd9;--paper:#fcfbf8;background:transparent;border:0;border-radius:0;padding:0;max-width:100%;color:var(--ink)}
section[id] h2{color:#233342;font-family:Georgia,"Noto Serif SC",SimSun,serif;font-weight:500;font-size:29px;line-height:1.5}
section[id]>header{border-bottom:1px solid #d6dcd9}section[id] p{line-height:1.9}
section[id] [class*="formula"]{max-width:100%;overflow-x:auto}
section[id] [class*="panel"],section[id] [class*="workbench"]{box-shadow:none}
@media(max-width:600px){section[id] div{min-width:0;max-width:100%}section[id] h2{font-size:25px}section[id] [class*="grid"]{grid-template-columns:minmax(0,1fr)}section[id] .pm-matrix-grid{grid-template-columns:repeat(3,minmax(0,1fr))}section[id] .pm-input-row input{min-width:0;flex:1;width:0}section[id] .pm-control-group{flex-wrap:wrap}section[id] .pm-control-group label{min-width:0;flex-basis:100%}section[id] .pm-section-header{flex-wrap:wrap}section[id] .pm-lab-panel,section[id] .interaction-panel{padding:14px}section[id] .pm-head-visual{display:block}section[id] .pm-control-group span{min-width:0}}
